<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';
type Row=Record<string,any>;
const me=ref<Row|null>(null), devices=ref<Row[]>([]),tunnels=ref<Row[]>([]),history=ref<Row[]>([]),admin=ref<Row>({nodes:[],plans:[],batches:[],users:[]}),audits=ref<Row[]>([]);
const page=ref('overview'),message=ref(''),error=ref(''),busy=ref(false),registering=ref(false);
const login=ref({email:'',password:'',otp:''}),reauth=ref({password:'',otp:''}),redeemCode=ref(''),bindName=ref('我的电脑'),binding=ref(''),exportCodes=ref(''),nodeSecret=ref('');
const tunnel=ref({name:'我的服务',device_id:'',protocol:'tcp',local_host:'127.0.0.1',local_port:22,remote_port:0});
const node=ref({name:'主节点',host:'node.example.com',control_start:17000,control_end:17099,port_start:20000,port_end:20999});
const plan=ref({name:'基础套餐',node_id:'',max_devices:1,max_tunnels:3,tunnel_kibps:1024,price_cents:990});
const cards=ref({name:'30天卡',note:'',plan_id:'',seconds:2592000,count:10,deadline:new Date(Date.now()+90*86400000).toISOString().slice(0,16)});
const adjustment=ref({user_id:'',seconds:3600,reason:'服务故障补偿'});
const rights=computed(()=>me.value?.entitlements?.[0]);
const remaining=computed(()=>{if(!rights.value)return '尚未激活';const seconds=Math.max(0,(new Date(rights.value.expires_at).getTime()-Date.now())/1000);return seconds>86400?`${Math.floor(seconds/86400)} 天 ${Math.floor(seconds%86400/3600)} 小时`:`${Math.floor(seconds/3600)} 小时 ${Math.floor(seconds%3600/60)} 分钟`});
const isAdmin=computed(()=>me.value&&me.value.role!=='user');
const date=(x:any)=>x?new Date(x).toLocaleString():'—';
async function api(path:string,method='GET',body?:any,sensitive=false){
 const headers:Record<string,string>={'Content-Type':'application/json'};
 if(sensitive){headers['X-Admin-Password']=reauth.value.password;headers['X-Admin-OTP']=reauth.value.otp;}
 const response=await fetch('/api'+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body)});
 const data=await response.json();if(!response.ok)throw new Error(data.error||`请求失败 ${response.status}`);return data;
}
async function refresh(){me.value=await api('/me');[devices.value,tunnels.value,history.value]=await Promise.all([api('/devices'),api('/tunnels'),api('/redemptions')]);if(isAdmin.value){admin.value=await api('/admin/overview');audits.value=await api('/admin/audit');}}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function signIn(){await action(async()=>{if(registering.value){await api('/register','POST',{email:login.value.email,password:login.value.password});registering.value=false;message.value='注册成功，请登录。';return;}await api('/login','POST',login.value);login.value.password='';login.value.otp='';await refresh();});}
async function signOut(){await action(async()=>{await api('/logout','POST',{});me.value=null;reauth.value={password:'',otp:''};nodeSecret.value='';exportCodes.value='';});}
// Keep the request id for a failed/retried redemption. The server also deduplicates the card itself.
let pendingCode='',pendingID='';
async function redeem(){await action(async()=>{if(pendingCode!==redeemCode.value){pendingCode=redeemCode.value;pendingID=crypto.randomUUID();}const r=await api('/redeem','POST',{code:redeemCode.value,request_id:pendingID});message.value=`${r.repeated?'该卡已兑换，未重复加时':'兑换成功'}，有效期至 ${date(r.after_at)}`;redeemCode.value='';await refresh();});}
async function bind(){await action(async()=>{const r=await api('/bind-codes','POST',{name:bindName.value});binding.value=r.code;message.value='绑定码 5 分钟内有效，仅可使用一次。';});}
async function createTunnel(){await action(async()=>{const r=await api('/tunnels','POST',tunnel.value);message.value=`已保存，远程端口 ${r.remote_port}。节点及客户端通常在 5 秒内获取，请实际测试连通。`;await refresh();});}
async function toggle(t:Row){await action(async()=>{await api('/tunnels/'+t.id,'PATCH',{name:t.name,local_host:t.local_host,local_port:t.local_port,paused:!t.paused});await refresh();message.value='配置已保存。应用新配置会中断该设备现有连接。';});}
async function remove(t:Row){await action(async()=>{await api('/tunnels/'+t.id,'DELETE');await refresh();message.value='隧道已删除，端口已回收。';});}
async function revoke(d:Row){await action(async()=>{await api(`/devices/${d.id}/revoke`,'POST',{});await refresh();message.value='设备已撤销，节点最迟 16 秒内停止转发。';});}
async function createNode(){await action(async()=>{nodeSecret.value=JSON.stringify(await api('/admin/nodes','POST',node.value,true),null,2);await refresh();message.value='节点已创建，请立即保存下方一次性凭据。';});}
async function createPlan(){await action(async()=>{await api('/admin/plans','POST',plan.value,true);await refresh();message.value='套餐已创建，规则固定；变更规则请创建新套餐。';});}
async function generate(){await action(async()=>{const r=await api('/admin/cards','POST',{...cards.value,deadline:new Date(cards.value.deadline+'Z').toISOString()},true);exportCodes.value=r.codes.join('\n');await refresh();message.value='充值码仅显示一次，请下载并安全交付给用户。';});}
async function disableBatch(id:string){await action(async()=>{await api(`/admin/batches/${id}/disable`,'POST',{},true);await refresh();message.value='本批次未兑换卡密已禁用。已发放权益保持账目记录。';});}
async function userState(u:Row){await action(async()=>{await api(`/admin/users/${u.id}/state`,'POST',{disabled:!u.disabled},true);await refresh();message.value='账号状态已更新，禁用会阻断登录和节点授权。';});}
async function nodeState(n:Row){await action(async()=>{await api(`/admin/nodes/${n.id}/state`,'POST',{enabled:!n.enabled},true);await refresh();message.value='节点状态已更新。';});}
async function adjust(){await action(async()=>{await api(`/admin/users/${adjustment.value.user_id}/adjust`,'POST',{seconds:adjustment.value.seconds,reason:adjustment.value.reason},true);await refresh();message.value='调整已记入独立流水和审计。';});}
function download(){const blob=new Blob([exportCodes.value+'\n'],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='充值码-'+Date.now()+'.txt';a.click();URL.revokeObjectURL(url);}
onMounted(async()=>{try{await refresh();}catch{/* show login */}});
</script>

<template>
 <div v-if="!me" class="login-wrap"><div class="login-card"><div class="brand">↗ <span>FRP 服务中心</span></div><p class="eyebrow">连接你的服务</p><h1>{{registering?'创建账号':'欢迎回来'}}</h1><p class="muted">管理设备、开通隧道和续费时长。</p><form @submit.prevent="signIn"><label>邮箱<input v-model="login.email" type="email" autocomplete="username" required></label><label>密码（至少 12 字节）<input v-model="login.password" type="password" :autocomplete="registering?'new-password':'current-password'" minlength="12" required></label><label v-if="!registering">管理员动态验证码<input v-model="login.otp" inputmode="numeric" autocomplete="one-time-code" placeholder="普通用户留空"></label><button :disabled="busy">{{registering?'注册':'登录'}}</button></form><button class="link" @click="registering=!registering">{{registering?'已有账号？去登录':'还没有账号？注册'}}</button><p class="error" v-if="error" role="alert">{{error}}</p><p class="success" v-if="message">{{message}}</p><p class="small muted">密码丢失请联系运营人员。本阶段尚未启用邮件找回。</p></div></div>
 <div v-else class="shell"><aside><div class="brand">↗ <span>FRP 服务中心</span></div><p class="eyebrow">用户工作台</p><nav><button v-for="item in [['overview','服务概览'],['tunnels','隧道管理'],['devices','我的设备'],['renew','充值续费'],['help','使用帮助']]" :class="{active:page===item[0]}" @click="page=item[0]">{{item[1]}}</button><template v-if="isAdmin"><p class="eyebrow">运营管理</p><button v-for="item in [['admin','套餐与节点'],['cards','充值码管理'],['users','用户与权益'],['audit','操作审计']]" :class="{active:page===item[0]}" @click="page=item[0]">{{item[1]}}</button></template></nav><div class="account"><span>{{me.email}}</span><small>{{me.role==='super'?'超级管理员':me.role==='operator'?'运营管理员':'普通用户'}}</small><button class="link" @click="signOut">退出登录</button></div></aside>
 <main><header><div><p class="eyebrow">服务控制台 / {{new Date().toLocaleDateString()}}</p><h1>{{({overview:'服务概览',tunnels:'隧道管理',devices:'我的设备',renew:'充值续费',help:'使用帮助',admin:'套餐与节点',cards:'充值码管理',users:'用户与权益',audit:'操作审计'} as Row)[page]}}</h1></div><button class="secondary" @click="action(refresh)" :disabled="busy">刷新数据</button></header>
 <p class="error notice" v-if="error" role="alert">{{error}}</p><p class="success notice" v-if="message" role="status">{{message}}</p>
 <section v-if="isAdmin&&['admin','cards','users'].includes(page)" class="reauth"><strong>敏感操作验证</strong><input type="password" autocomplete="off" v-model="reauth.password" placeholder="管理员密码"><input inputmode="numeric" autocomplete="off" v-model="reauth.otp" placeholder="当前 6 位动态验证码"><small>密码和验证码仅保留在本页面内存中。</small></section>
 <template v-if="page==='overview'"><div class="stats"><section class="card"><p class="muted">当前套餐</p><h2>{{rights?.name||'尚未激活'}}</h2><span class="badge">{{rights&&new Date(rights.expires_at)>new Date()?'使用中':'待续费'}}</span></section><section class="card"><p class="muted">剩余时长</p><h2>{{remaining}}</h2><small>离线也消耗有效期</small></section><section class="card"><p class="muted">隧道 / 套餐上限</p><h2>{{tunnels.length}} <span class="muted">/ {{rights?.max_tunnels||0}}</span></h2><small>TCP 与 UDP 合计</small></section></div><section class="card"><h2>连接信息</h2><dl><dt>到期时间</dt><dd>{{date(rights?.expires_at)}}</dd><dt>转发节点</dt><dd>{{rights?.node_name||'—'}} {{rights?.host||''}}</dd><dt>节点最近通讯</dt><dd>{{date(rights?.last_seen)}}</dd><dt>单隧道带宽</dt><dd>{{rights?.tunnel_kibps||0}} KiB/s，服务端限制</dd></dl><p class="warning" v-if="rights&&(new Date(rights.expires_at).getTime()-Date.now())<3*86400000">套餐将于三天内到期或已经到期，请及时兑换续费卡。</p><button @click="page='devices'">绑定设备</button> <button class="secondary" @click="page='renew'">充值续费</button></section><section class="card"><h2>开始使用</h2><ol><li>兑换充值码激活套餐。</li><li>生成一次性绑定码，在电脑上运行 CLI 绑定设备。</li><li>创建隧道，启动客户端，使用公网节点地址和远程端口访问。</li></ol><p class="muted">第一阶段支持 TCP/UDP、按自然经过时间计费；实时流量、总流量配额和在线人数统计尚未提供。</p></section></template>
 <template v-if="page==='renew'"><section class="card narrow"><h2>兑换充值码</h2><p class="muted">同套餐续费从当前到期时间与服务器当前时间中较晚者开始累加。一天固定为 24 小时，30 天卡不等于自然月。</p><form @submit.prevent="redeem"><label>充值码<input v-model="redeemCode" required placeholder="XXXXXXXX-XXXXXXXX-XXXXXXXX-XXXXXXXX"></label><button :disabled="busy">确认兑换</button></form></section><section class="card"><h2>充值记录</h2><div class="table-wrap"><table><thead><tr><th>批次</th><th>兑换时间</th><th>原到期时间</th><th>新到期时间</th></tr></thead><tbody><tr v-for="r in history" :key="r.id"><td>{{r.name}}</td><td>{{date(r.created_at)}}</td><td>{{date(r.before_at)}}</td><td>{{date(r.after_at)}}</td></tr></tbody></table></div><p v-if="!history.length" class="empty">尚无兑换记录</p></section></template>
 <template v-if="page==='devices'"><section class="card narrow"><h2>绑定新设备</h2><form @submit.prevent="bind"><label>设备名称<input v-model="bindName" required></label><button :disabled="busy">生成 5 分钟绑定码</button></form><pre v-if="binding">{{binding}}</pre><p class="small muted">在客户端运行 portal bind --config agent.json，按提示输入此码。不要分享设备配置文件。</p></section><section class="card"><h2>设备列表</h2><div v-for="d in devices" :key="d.id" class="item"><div><strong>{{d.name}}</strong><p class="small muted">{{d.id}} · {{d.revoked?'已撤销':'已绑定'}} · 节点通讯 {{date(d.node_last_seen)}}</p></div><button v-if="!d.revoked" class="danger" @click="revoke(d)" :disabled="busy">撤销凭据</button></div><p v-if="!devices.length" class="empty">还没有绑定设备</p></section></template>
 <template v-if="page==='tunnels'"><section class="card"><h2>创建隧道</h2><form class="grid-form" @submit.prevent="createTunnel"><label>名称<input v-model="tunnel.name" required></label><label>设备<select v-model="tunnel.device_id" required><option value="" disabled>请选择设备</option><option v-for="d in devices.filter(d=>!d.revoked)" :value="d.id">{{d.name}}</option></select></label><label>协议<select v-model="tunnel.protocol"><option value="tcp">TCP</option><option value="udp">UDP</option></select></label><label>本地地址<input v-model="tunnel.local_host" required></label><label>本地端口<input type="number" v-model.number="tunnel.local_port" min="1" max="65535" required></label><label>远程端口（0 为自动分配）<input type="number" v-model.number="tunnel.remote_port" min="0" max="65535"></label><button :disabled="busy">创建隧道</button></form><p class="small muted">常用 TCP 端口：SSH 22、远程桌面 3389、网站 80。公网入口需有公网 IP 和安全组放行。</p></section><section class="card"><h2>我的隧道</h2><div v-for="t in tunnels" :key="t.id" class="tunnel-item"><div><strong>{{t.name}}</strong> <span class="badge">{{t.protocol.toUpperCase()}}</span><p><code>{{t.node_host}}:{{t.remote_port}}</code> → <code>{{t.local_host}}:{{t.local_port}}</code></p><small class="muted">{{t.paused?'已暂停':'配置已保存'}} · 实际生效请通过连通测试及节点日志确认</small></div><div class="actions"><button class="secondary" @click="toggle(t)" :disabled="busy">{{t.paused?'恢复':'暂停'}}</button><button class="danger" @click="remove(t)" :disabled="busy">删除</button></div></div><p v-if="!tunnels.length" class="empty">创建第一条隧道，连接你的本地服务。</p></section></template>
 <template v-if="page==='admin'"><section class="card"><h2>添加转发节点</h2><form class="grid-form" @submit.prevent="createNode"><label>名称<input v-model="node.name" required></label><label>公网主机名 / IP<input v-model="node.host" required></label><label>控制端口开始<input type="number" v-model.number="node.control_start"></label><label>控制端口结束<input type="number" v-model.number="node.control_end"></label><label>业务端口开始<input type="number" v-model.number="node.port_start"></label><label>业务端口结束<input type="number" v-model.number="node.port_end"></label><button :disabled="busy">创建节点</button></form><pre v-if="nodeSecret">{{nodeSecret}}</pre><p class="warning" v-if="nodeSecret">凭据仅显示一次，请安全保存到 node.json。离开或刷新页面将失去明文。</p></section><section class="card"><h2>创建固定规则套餐</h2><form class="grid-form" @submit.prevent="createPlan"><label>名称<input v-model="plan.name" required></label><label>节点<select v-model="plan.node_id" required><option value="" disabled>选择节点</option><option v-for="n in admin.nodes" :value="n.id">{{n.name}}</option></select></label><label>设备数上限<input type="number" v-model.number="plan.max_devices" min="1" max="16"></label><label>账号总隧道数<input type="number" v-model.number="plan.max_tunnels" min="1" max="128"></label><label>单隧道 KiB/s<input type="number" v-model.number="plan.tunnel_kibps" min="1"></label><label>参考价格（分）<input type="number" v-model.number="plan.price_cents" min="0"></label><button :disabled="busy">创建套餐</button></form><p class="small muted">套餐绑定单个节点。每隧道限速独立；未提供全账号总带宽或流量额度，参考价格不代表在线支付收入。</p></section><section class="card"><h2>节点状态</h2><div v-for="n in admin.nodes" class="item"><div><strong>{{n.name}}</strong><p>{{n.host}} · {{n.enabled?'可授权':'维护中'}} · 最近通讯 {{date(n.last_seen)}}</p></div><button class="secondary" @click="nodeState(n)" :disabled="busy">{{n.enabled?'停止授权':'恢复授权'}}</button></div><h2>已建套餐</h2><p v-for="p in admin.plans">{{p.name}} · {{p.max_devices}} 台设备 · {{p.max_tunnels}} 条隧道 · {{p.tunnel_kibps}} KiB/s/隧道</p></section></template>
 <template v-if="page==='cards'"><section class="card"><h2>批量生成时长卡</h2><form class="grid-form" @submit.prevent="generate"><label>批次名称<input v-model="cards.name" required></label><label>套餐<select v-model="cards.plan_id" required><option value="" disabled>选择套餐</option><option v-for="p in admin.plans" :value="p.id">{{p.name}}</option></select></label><label>卡时长<select v-model.number="cards.seconds"><option :value="3600">1 小时</option><option :value="86400">1 天（24 小时）</option><option :value="604800">7 天</option><option :value="2592000">30 天（固定天数）</option><option :value="7776000">90 天</option><option :value="31536000">365 天</option></select></label><label>自定义总秒数<input v-model.number="cards.seconds" type="number" min="1"></label><label>数量（1–1000）<input v-model.number="cards.count" type="number" min="1" max="1000"></label><label>兑换截止时间（UTC）<input type="datetime-local" v-model="cards.deadline" required></label><label>备注<input v-model="cards.note"></label><button :disabled="busy">生成并一次性导出</button></form><template v-if="exportCodes"><textarea v-model="exportCodes" readonly rows="8"></textarea><button @click="download">下载卡密文本</button> <button class="secondary" @click="exportCodes=''">清除页面明文</button></template></section><section class="card"><h2>充值批次</h2><div v-for="b in admin.batches" class="item"><div><strong>{{b.name}}</strong><p>{{b.seconds}} 秒 · 共 {{b.card_count}} 张 · 已兑 {{b.redeemed_count}} · 禁用 {{b.disabled_count}}</p><small class="muted">截止 {{date(b.deadline)}}</small></div><button class="danger" @click="disableBatch(b.id)" :disabled="busy">禁用未兑换卡</button></div></section></template>
 <template v-if="page==='users'"><section class="card"><h2>用户管理</h2><div v-for="u in admin.users" class="item"><div><strong>{{u.email}}</strong><p>{{u.role}} · {{u.disabled?'已禁用':'正常'}} · {{u.plan_name||'未激活'}} · 到期 {{date(u.expires_at)}}</p></div><button v-if="u.role==='user'" class="secondary" @click="userState(u)" :disabled="busy">{{u.disabled?'解禁':'禁用'}}</button></div></section><section class="card narrow"><h2>权益调整</h2><form @submit.prevent="adjust"><label>用户<select v-model="adjustment.user_id" required><option value="" disabled>选择用户</option><option v-for="u in admin.users" :value="u.id">{{u.email}}</option></select></label><label>调整秒数（负数为扣减）<input type="number" v-model.number="adjustment.seconds" required></label><label>原因<input v-model="adjustment.reason" minlength="4" required></label><button :disabled="busy">记录并应用调整</button></form></section></template>
 <template v-if="page==='audit'"><section class="card"><h2>最近 500 条操作</h2><div class="table-wrap"><table><thead><tr><th>时间</th><th>操作</th><th>目标</th><th>详情</th></tr></thead><tbody><tr v-for="a in audits" :key="a.id"><td>{{date(a.created_at)}}</td><td>{{a.action}}</td><td><code>{{a.target}}</code></td><td><pre>{{JSON.stringify(a.detail,null,2)}}</pre></td></tr></tbody></table></div></section></template>
 <template v-if="page==='help'"><section class="card"><h2>从本地服务到公网访问</h2><ol><li>先确认本地服务可用。例如 SSH 服务监听 127.0.0.1:22。</li><li>在「我的设备」生成绑定码，使用管理员提供的程序和 CA 证书。</li><li>运行 <code>portal bind --config agent.json</code> 输入绑定码，再运行 <code>portal agent --config agent.json</code>。</li><li>在「隧道管理」创建 TCP/UDP 隧道。本地地址以客户端所在电脑为准。</li><li>用其他网络访问「节点地址:远程端口」。UDP 需要对应应用层测试。</li></ol><h2>连接失败排查</h2><p>运行 <code>portal diagnose --config agent.json</code> 检查凭据、DNS、节点控制端口和 TCP 本地服务。检查套餐是否到期、设备是否撤销，以及节点端口是否被防火墙阻挡。</p><h2>续费和停止规则</h2><p>有效期按服务端自然经过时间计算，离线不暂停。同套餐续费累加时间；过期、禁用或撤销后，节点在最多 16 秒内关闭已有转发并拒绝新授权。控制平台中断时也按短期租约停止。</p><p class="muted">完整安装、升级、卸载、安全配置及备份恢复操作请阅读交付包 docs/安装与使用手册.md。HTTP/HTTPS、桌面 GUI、在线支付和按流量计费尚未提供。</p></section></template>
 <footer>FRP Portal 0.1.1 · 时间以服务器为准 · 本地显示时区 {{Intl.DateTimeFormat().resolvedOptions().timeZone}}</footer>
 </main></div>
</template>
